<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>In đơn hàng</h1>        <ol class="breadcrumb">            <li><a href="/<?php echo ADMIN_URL; ?>"><i class="fa fa-dashboard"></i> Home</a></li>            <li class="active">In đơn hàng</li>        </ol>            <select class="form-control" style="width: 20%;float: left;margin-right: 10px;" id="shipping_type">                    <option value="post_office" <?php echo $shipping_type == 'post_office' ? 'selected' : ''; ?>>Bưu điện</option>            <option value="f_shipping" <?php echo $shipping_type == 'f_shipping' ? 'selected' : ''; ?>>Chuyển phát nhanh</option>        </select>        <a href="javascript:void(0)"><button style="width: 200px;float: left;margin-right: 10px;" class="btn btn-block btn-primary button">Xuất hoá đơn</button></a>                     </section>    <br/>    <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><script>    $('#shipping_type').change(function () {        load_list();    });    var status = "<?php echo $status; ?>";    function load_list() {        var phone = $('#phone').val();        var shipping_type = $('#shipping_type').val();        $.post('<?php echo base_url() . ADMIN_URL; ?>export_shipping/load_list', {status: status, shipping_type: shipping_type}, function (result) {            $('#list_ajax').html(result);        });    }    load_list();    $(".button").click(function () {        $('body').append('<meta http-equiv="refresh" content="0">');        var shipping_type = $('#shipping_type').val();        window.open('<?php echo base_url() . ADMIN_URL; ?>export_shipping/print_order/' + shipping_type + '/<?php echo @$status; ?>', 'in hoá đơn', 'toolbar=no, location=no, directories=no, status=no, menubar=no, scrollbars=no, resizable=no, copyhistory=no, width=' + 1000 + ', height=' + 1000 + ', top=' + 0 + ', left=' + 0);    });</script>